changeSet.sql:
CREATE TABLE person_company_links (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    person_id TEXT NOT NULL,
    company_id TEXT NOT NULL REFERENCES companies (company_id),
    city_name TEXT,
    regional_center_name TEXT,
    UNIQUE (person_id, company_id)
);
CREATE INDEX person_company_links_company_id_idx ON person_company_links (company_id);

CREATE TABLE company_payment_summaries (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    payer_company_id TEXT NOT NULL REFERENCES companies (company_id),
    recipient_company_id TEXT NOT NULL REFERENCES companies (company_id),
    total_payment_amount NUMERIC NOT NULL CHECK (total_payment_amount >= 0),
    payment_count BIGINT NOT NULL CHECK (payment_count >= 0),
    UNIQUE (payer_company_id, recipient_company_id)
);
CREATE INDEX company_payment_summaries_recipient_idx
    ON company_payment_summaries (recipient_company_id);
